ST.xhtml:p:
IF g_fCuttingType = 1 THEN
   nLayerStartState := 0;
   nLayerStartState_bak :=0;
   nLayerEndState_bak := 0;
   nLayerEndState := 0;
   RETURN;

END_IF;



RTrigger_Layerstart(CLK := g_bLayerStartM);
RTrigger_Layerend(CLK := g_bLayerEndM);
RTrigger_Corner_in(CLK := g_bLaserOnCornerM OR g_biLaserOnCorner);
RTrigger_Corner_out(CLK := g_bLaserOutCornerM OR g_biLaserOutCorner);
RTrigger_FirstGas(CLK := g_bStartRunOpenGasM);
RTrigger_UpLift(CLK := g_biLayerEndUplift OR g_bLayerEndUpliftM);
RTriggerClaw3UpLift(CLK := g_biClaw3UpLift OR g_bClaw3UpLiftM);
RTriggerProfileStart(CLK := g_bProfileStartM);(*从这里进来，说明该轮廓是板外切割profile_start*)
RTriggerProfileLaserGasStart(CLK := g_bProfileLaserGasM);
RTrigger_ProcessEnd(CLK := g_bPlcEndM OR g_bProcessEndM);
RTrigger_LayerstartOffLaser(CLK := g_bLayerStartOffLaserM);(*从这里进来，说明需要开随动而不开光 *)
RTringChangeToolNum(CLK := g_bChangeCutToolNumberM);
nToolNum := g_nToolNum;

(*输出拐角速度*)
g_doCornerSpeed := g_TechData.multilTechData[nToolNum-1].CornerCompen.dSpeed;
(*输出进/出拐角冷却时间*)
g_dCutHeight := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Height;
(*将切割高度传给CNC,不切割状态默认传第一把刀具的切割高度*)
g_doCutHeightToCNC := g_dCutHeight;
IF g_nPlcState = 0 THEN
  g_doCutHeightToCNC := g_TechData.multilTechData[0].DIRECUT_CUTTING.fCutting_Height;
END_IF;

g_foInCornerCoolTime := DINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].CornerCompen.nInCornerCloseLaserTime)/1000.0;
g_foOutCornerCoolTime := DINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].CornerCompen.nOutCornerCloseLaserTime)/1000.0;






(*g_dActG00OpenGasTime:= TIME_TO_LREAL(TON_FrogLeapOpenGas.ET); *)(*实际蛙跳空行提前开气时间,参考平面暂时没用上*) 
(*关气延时到了，就关气，如果在这个过程中又来了开气的指令，则忽略关气*)
(*在Layer end中已经实现了关气，所以不需要再在LayerStart中处理bCloseGasDelayEnable*)
(*但是为了安全起见，还是在Layerstart里面对bCloseGasDelayEnable置false*)
IF RTrigger_Layerstart.Q THEN
  bCloseGasDelayEnable := FALSE;
END_IF;
TON_CloseGasDelay(IN := bCloseGasDelayEnable, PT := LREAL_TO_TIME(FUN_MStoS(nCloseGasDelayTime)));
IF TON_CloseGasDelay.Q THEN
      g_bgas_enable := FALSE;(*关闭气阀的数字量输出*)
      bCloseGasDelayEnable := FALSE;
END_IF;

(*提前吹气:在卡盘避让,分中都不进行提前吹气  分中由于nLayerEndState=600的时候回关闭分中的标志 所以这里重新赋值一下 分中结束后关闭标志*)
IF g_dNestingIsUseSideCenterM = 1.0  THEN
  g_bCloseGasInAdvance := TRUE;
END_IF;
IF NOT (g_dNestingDistanceToGoM=0.0 AND g_dNestingMotionAngleM=0.0 AND g_bNestingIsPartEnd) AND g_dNestingIsUseSideCenterM = 0.0 
      AND g_dNestingIsPullerM <> 1.0 AND NOT g_bCloseGasInAdvance AND NOT (g_bDryRunEnable OR g_bDebugMode) THEN
  IF (g_diG00Time_rem <=FUN_MSTOS(LREAL_TO_DINT(g_dG00OpenGasTime))+0.001 AND g_diG00Time_rem > 0.001) AND g_diG00Time_rem <> g_diLastG00Time_rem AND g_dG00OpenGasTime > 0.001 AND nLayerEndState = 601 THEN
    IF g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[0].bPierEnable THEN
      for indx := 2 to 0 BY -1 DO
        if (g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[indx].bPierEnable) then
          g_ugas_type := g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[indx].Piercing_Gas;
          g_dmaster_pressure := g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[indx].Piercing_Gas_Pressure;
          g_dair_pressure := g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[indx].Piercing_Gas_Pressure;
          g_doxygen_pressure := g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[indx].Piercing_Gas_Pressure;
          g_dnitogen_pressure := g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[indx].Piercing_Gas_Pressure;
          EXIT;(*退出循环*)
        end_if;
      end_for;
    ELSE
      g_ugas_type := g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.nCutting_Gas;
      g_dmaster_pressure := g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_dair_pressure := g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_doxygen_pressure := g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_dnitogen_pressure := g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
    END_IF;  
    g_bgas_enable := TRUE;
  END_IF;     
END_IF;  
TON_FrogLeapOpenGas(In :=g_bgas_enable, PT := T#20s);  (*开气计时器*)


IF g_nOpenGasDelayTime<5 THEN(*开气延时最小5ms，保证气比光先出5ms*)
  g_nOpenGasDelayTime := 5;
END_IF;

IF RTrigger_FirstGas.Q THEN
  g_bFirstGas := TRUE;
  g_bStartRunOpenGasM := FALSE;
END_IF;

g_foCuttingSpeed := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Speed *1000.0;
IF RTrigger_Layerstart.Q THEN
  g_bLayerStartM := FALSE;
  IF g_bDryRunEnable OR g_bDebugMode OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack OR g_bForwardStatusFb THEN
    nLayerStartState := 500;
    bLookBackDone := FALSE;
  ELSE
    nLayerStartState := 9;
  END_IF;
  nLayerEndState := 0;
  TON_PauseStopLaserDelay(IN :=FALSE);(*暂停关光延时*)
  g_bProfileEnable := FALSE;
  g_bProfileLaserEnable := FALSE;
  (*bUpLiftFlag := FALSE;
  bClaw3UpLiftFlag := FALSE;*)
END_IF;
Ton_FocusTimeout(IN := bFocusEnable,PT := LREAL_TO_TIME(FUN_MStoS(g_dFocusTimeOut)));
IF Ton_FocusTimeout.Q THEN
  bFocusEnable := FALSE;
  Ton_FocusTimeout(IN := FALSE);
  IF NOT g_bFocusDone THEN
    g_bFocusTimeOutAlarm := TRUE;
  END_IF;
END_IF;



(*板外切割-随动定高：随动定高后上抬*)
IF RTriggerProfileStart.Q THEN
  IF g_bDryRunEnable OR g_bDebugMode OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack OR g_bForwardStatusFb THEN
    nLayerStartState := 501;
    bLookBackDone := FALSE;
    M.ENABLE[230] := 0;
    IF g_dProfileCuttingPos = 0.0 THEN
        g_dProfileCuttingPos := g_dProfileCuttingSimPos + g_dProfileAltimetricCompensation;
    END_IF;
  ELSE
    g_dProfileCuttingPos := 0.0;(*板外切割时，随动下来记录的坐标，用于暂停后开始寸动下来时使用*)
    nLayerStartState := 9;
  END_IF;
  nLayerEndState := 0;

  TON_PauseStopLaserDelay(IN :=FALSE);(*暂停关光延时*)
  g_bProfileEnable := TRUE;
  g_bProfileFollowEnable := FALSE;(*板外切割开随动标志位清零*)
  g_bProfileStartM := FALSE;
  dM230PValue := M.PARAMETER_P[230];

END_IF;
(*板外切割开始触发，跳过穿孔、随动，直接定高开始出气、出光切割*)
IF RTriggerProfileLaserGasStart.Q THEN
  g_bProfileLaserGasM  := FALSE;
  g_bProfileLaserEnable := TRUE;
  bCloseGasDelayEnable := FALSE;
  IF g_bDryRunEnable OR g_bDebugMode OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack OR g_bForwardStatusFb THEN
    nLayerStartState := 500;
    bLookBackDone := FALSE;
  ELSE
    g_boCNCMoveDisable := TRUE;
    nLayerStartState := 400;
    IF bLookBackDone THEN
      bLookBackDone := FALSE;
      IF g_niMotionType > 1 THEN
        IF g_bRapidContinue THEN (*快捷继续*) 
          g_bRapidContinue := FALSE;
          nLayerStartState := 400;
        ELSE
          nLayerStartState := 11;
        END_IF;
      END_IF;
    END_IF;
    IF g_niFllowStatusFromCNC = 1 THEN (*在定高,直接切割*)
      nLayerStartState := 400;
      g_bProfileEnable := TRUE;
    END_IF;
  END_IF;
  nLayerEndState := 0;
  g_bProfileFollowEnable := FALSE;(*板外切割开随动标志位清零*)
END_IF;

IF RTrigger_Layerend.Q THEN
  g_bLayerEndM := FALSE;
  g_bLayerStartOffLaser:= FALSE;(*开随动不开关状态标志位*)
  IF g_bDryRunEnable OR g_bDebugMode OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack OR g_bForwardStatusFb THEN
    nLayerEndState := 600;
  ELSE
    nLayerEndState := 10;
  END_IF;
  nLayerStartState := 0;
  g_boLayerEndDone := FALSE;
  bClaw3UpLiftFlag := FALSE;
  bUpLiftFlag := FALSE;
  g_bProfileEnable := FALSE;
  g_bProfileLaserEnable := FALSE;
  g_bProfileFollowEnable := FALSE;(*板外切割开随动标志位清零*)
END_IF;

IF RTrigger_UpLift.Q THEN
  bUpLiftFlag := TRUE;
  g_bLayerEndUpliftM  := FALSE;
END_IF;

IF RTriggerClaw3UpLift.Q THEN
  IF g_bDryRunEnable OR g_bDebugMode OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack OR g_bForwardStatusFb THEN
    bClaw3UpLiftFlag := FALSE;
    g_boClaw3UpLiftDone := TRUE;
  ELSE
    bClaw3UpLiftFlag := TRUE;
    g_boClaw3UpLiftDone := FALSE;    
  END_IF;
  g_bClaw3UpLiftM := FALSE;  
END_IF;

IF RTrigger_ProcessEnd.Q THEN
  nLayerStartState := 0;
  nLayerEndState := 0;
  g_bProcessEndM := FALSE;
  g_bProfileProbeCompletionFlag := FALSE;
  bInCornerFalg := FALSE;
END_IF;

IF RTrigger_LayerstartOffLaser.Q THEN
  g_bLayerStartOffLaserM := FALSE;
  g_bLayerStartOffLaser:= TRUE;(*开随动不开关状态标志位*)
  IF g_bDryRunEnable OR g_bDebugMode OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack OR g_bForwardStatusFb THEN
    nLayerStartState := 500;
    bLookBackDone := FALSE;
  ELSE
    nLayerStartState := 9;
  END_IF;
  nLayerEndState := 0;
  TON_PauseStopLaserDelay(IN :=FALSE);(*暂停关光延时*)
  g_bProfileEnable := FALSE;
  g_bProfileLaserEnable := FALSE;
  (*bUpLiftFlag := FALSE;
  bClaw3UpLiftFlag := FALSE;*)
END_IF;
IF RTringChangeToolNum.Q THEN
  g_bChangeCutToolNumberM := FALSE;
  IF nLayerStartState = 500 AND NOT (g_bDryRunEnable OR g_bDebugMode OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack OR g_bForwardStatusFb) THEN
    IF g_ugas_type <> g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Gas THEN
      g_bgas_enable := FALSE;
      g_ugas_type := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Gas;
      g_dmaster_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_dair_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_doxygen_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_dnitogen_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_bgas_enable := TRUE;
    ELSE
      g_ugas_type := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Gas;
      g_dmaster_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_dair_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_doxygen_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_dnitogen_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
    END_IF;
	g_fZFollowHeight := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.fCutting_Height;
	g_foCuttingSpeed := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Speed *1000.0;
	g_dZoomPosition := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Focus; 
	g_bFocusEnable := TRUE;(*通知F轴调焦*)
	IF bInCornerFalg THEN
		g_nPower := DINT_TO_UINT(g_TechData.multilTechData[nToolNum-1].CornerCompen.nPower);
		g_nPwmFreq := DINT_TO_UINT(g_TechData.multilTechData[nToolNum-1].CornerCompen.nHz);
		g_nPwmDuty :=DINT_TO_UINT(g_TechData.multilTechData[nToolNum-1].CornerCompen.nDuty);
	ELSE
		g_nPower := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Power));
		g_nPwmFreq := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Frequency));
		g_nPwmDuty := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Duty));
    END_IF;
  END_IF;
END_IF;

CASE nLayerStartState OF
  0:(*空闲*)
    nLayerStartState := 0;
    nLayerStartState_bak := 0;
  9:(*关闭CNC运动使能*)
    nLayerStartState_bak := 9;
    g_boCNCMoveDisable := TRUE;
    g_nCurCutState :=0;
    bZHeightJudgeOpen := TRUE;
    g_bZFollowExecute := FALSE;
    g_bZRelExecute := FALSE;
    nLayerStartState := 10;
    bFocusEnable := FALSE;
    IF bLookBackDone THEN
      bLookBackDone := FALSE;
      IF g_niMotionType > 1 THEN
        IF g_bRapidContinue THEN (*快捷继续*) 
          g_bRapidContinue := FALSE;
          nLayerStartState := 400;
        ELSE
          nLayerStartState := 11;
        END_IF;
      END_IF;
    END_IF;
    g_bProfileProbeCompletionFlag := FALSE;
    IF g_bProfileEnable THEN
      nLayerStartState := 20;
      g_bProfileProbeCompletionFlag := TRUE;
    END_IF;
  10:
    nLayerStartState_bak := 10; 
    g_bZFollowClose := TRUE;
    g_nFollowState :=130;
    IF g_bZFollowOutDone THEN
      nLayerStartState := 11;
      g_bZFollowClose := FALSE;
    END_IF;
    g_nFrogLeapOpenGasTime := LREAL_TO_DINT(TIME_TO_LREAL(TON_FrogLeapOpenGas.ET)*1000.0); (*蛙跳到此时已出气时间ms*)
    IF g_nFrogLeapOpenGasTime >= g_nOpenGasDelayTime THEN
      g_nOpenGasDelayTimeAdd := 0;     (*蛙跳出气时间>=开气延时时间，就不需开气延时，否则开气延时时间要减去蛙跳出气时间*)
    ELSE
      g_nOpenGasDelayTimeAdd := ABS(g_nOpenGasDelayTime - g_nFrogLeapOpenGasTime);
    END_IF;
    (*TON_FrogLeapOpenGas(In := FALSE);*)
  11:(*判断切割类型*)
    nLayerStartState_bak := 11;
    g_nPiercingStatus := 1;
    IF g_TechData.multilTechData[nToolNum-1].NoninductivePiercing.bOpen THEN(*无感穿孔*)
      IF g_bLaserCuttingEnable THEN (*跳过开光*)
        nLayerStartState := 105;
      ELSE(*开光处理*)
         nLayerStartState := 100;
      END_IF;
    ELSIF g_TechData.multilTechData[nToolNum-1].NEW_MULTIL_PIERCING[0].bPierEnable THEN(*等级穿孔*)
      nLayerStartState := 200;
    ELSE(*直接切割*)
      nLayerStartState := 20;
    END_IF;
    IF g_bLayerStartOffLaser THEN(*不开光切割，穿孔就跳过了*)
      nLayerStartState := 20;
    END_IF;
  20:(*直接切割*)
    nLayerStartState_bak := 20;
    IF g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Height <= g_dZFollowMaxHeight THEN (*直接切割高度小于随动最大高度，直接到切割高度*)  
      nLayerStartState := 400;
      IF g_bProfileEnable THEN
        nLayerStartState := 50;
      END_IF;
    ELSE 
     g_bZFollowExecute := FALSE; 
     nLayerStartState := 25;
    END_IF;
  25:(*随动到1.0mm*)  
    nLayerStartState_bak := 25;
    g_fZFollowHeight := 1.0;
    g_bZFollowExecute := TRUE;
    g_bFocusDone := FALSE;
    g_dZoomPosition := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Focus;
    g_bFocusEnable := TRUE;(*通知F *) 
    nLayerStartState := 30;
  30:(*等待随动到位，并关随动*)     
    nLayerStartState_bak := 30; 
    g_nFollowState :=40; 
    IF g_bZFollowDone THEN 
      g_bZFollowExecute := FALSE;
      g_bZFollowClose := TRUE;
      nLayerStartState := 35;
      bZHeightJudgeOpen := FALSE;
    END_IF; 
  35: (*等待关随动到位*)  
    nLayerStartState_bak := 35;
    g_nFollowState :=131;
    IF g_bZFollowOutDone THEN
      g_bZFollowClose := FALSE;
     nLayerStartState := 40;
    END_IF; 
  40: (*上抬到切割高度，并出光出气*)  
    nLayerStartState_bak := 40;
    g_fZRelDistance := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.fCutting_Height - 1.0;
    g_bZRelExecute := TRUE; 
    IF g_bProfileEnable THEN(*板外切割：不出光不出气*)
      nLayerStartState := 45;
    ELSE(*出气*)
      g_ugas_type := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Gas;
      g_dmaster_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_dair_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_doxygen_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_dnitogen_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_bgas_enable := TRUE; 
      IF g_bFirstGas THEN
        IF g_bChangeGasFlag THEN 
          nTimeTemp := g_nFirstGasDelayTime + g_nChangeGasDelayTime;
        ELSE
          nTimeTemp := g_nFirstGasDelayTime;
        END_IF;
      ELSE
        IF g_bChangeGasFlag THEN 
          nTimeTemp := g_nChangeGasDelayTime;
        ELSE
          nTimeTemp := 0;
        END_IF;
      END_IF;
      IF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=0 THEN
        nTimeTemp := nTimeTemp + g_nOpenGasDelayTimeAdd;
      END_IF;
      TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nTimeTemp)));
      IF TON_FirstGasDelay.Q THEN
        TON_FirstGasDelay(IN :=FALSE);
        nLayerStartState := 45;
      END_IF;
    END_IF;

  45: (*上抬完成*)
    nLayerStartState_bak := 45;
    IF g_bZRelDone THEN
      g_bZRelExecute := FALSE;
      nLayerStartState := 50;
    END_IF;
    g_nPiercingStatus := 0;
    g_foCuttingSpeed := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Speed *1000.0;
  50: (*随动到切割高度*)
    nLayerStartState_bak := 50;
    g_fZFollowHeight := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.fCutting_Height;
    g_bZFollowExecute := TRUE;
    IF g_bProfileEnable THEN
      nLayerStartState := 55;
    ELSE
      nLayerStartState := 420;
    END_IF;

  55:(*等待切割随动到位*)(*板外切割：记录要定高的坐标，并且上抬*)
    nLayerStartState_bak := 55; 
     nLayerStartState := 58;
    IF bFrogLeapEnable THEN
      IF Axis_Z.NCTOPLC.AXISSTATE = 9 AND g_bZLeapForgDone THEN
        g_dProfileCuttingPos := Axis_Z.NCTOPLC.SETPOS;
        nLayerStartState := 60;
        bZHeightJudgeOpen := FALSE;
        g_bZFollowExecute := FALSE;
        IF dM230PValue = 1.0 THEN
          g_boCNCMoveDisable := FALSE;
          M.ENABLE[230] := 0;
          nLayerStartState := 0;
          nLayerEndState := 601;
          bZHeightJudgeOpen := FALSE;
          g_bProfileProbeCompletionFlag := FALSE;
        END_IF;
      END_IF;
    END_IF;
  58:
    g_nFollowState :=41; 
    IF g_bZFollowDone THEN
      g_bZFollowExecute := FALSE;
      g_dProfileCuttingPos := Axis_Z.NCTOPLC.SETPOS;
      bZHeightJudgeOpen := FALSE;
      g_bProfileProbeCompletionFlag := FALSE;
      IF dM230PValue = 0.0 THEN
        nLayerStartState := 60;
      ELSE
         g_boCNCMoveDisable := FALSE;
         M.ENABLE[230] := 0;
        nLayerStartState := 0; 
        nLayerEndState := 601; 
      END_IF;
    END_IF;
  60:(*板外切割：关随动*)
    nLayerStartState_bak := 55;
    g_bZFollowExecute := FALSE;
    g_bZFollowClose := TRUE;
    g_nFollowState :=132;
    IF g_bZFollowOutDone THEN
      g_bZFollowClose := FALSE;
      nLayerStartState := 65;
      (*根据不同管型，获取△上抬距离（安全距离） pipetype: 0、平面 1、圆 2、矩形 3、腰 4、椭圆 5、D型管 10、H钢 11、角钢*)
      dXCoordToCenter := ABS(g_diXMachineCoordinate - g_dBeamCenterPos);(*X轴当前坐标距离X轴中心的距离*)
      IF g_nPipeType = 1 THEN 
        IF dXCoordToCenter >= 0.5 THEN(*判断是平面孔情况的还是空间孔情况*) 
           (*如果轮廓跳转时检测到X轴不在中心位置，需要上抬保证安全*)
           dCircleLiftTemp := SQRT(g_dCircleRadius*g_dCircleRadius - dXCoordToCenter*dXCoordToCenter);
           dMaxChangeHeight := g_dCircleRadius - dCircleLiftTemp + 1.0;
        ELSE
          dMaxChangeHeight := 0.0; 
        END_IF;
      ELSIF g_nPipeType = 2 OR g_nPipeType = 11 THEN
        dMaxChangeHeight := SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0) - MIN(g_dSquareLenght,g_dSquareWidth)/2.0 + 10.0;
      ELSIF g_nPipeType = 3 OR g_nPipeType = 4 THEN  
        dMaxChangeHeight := (g_dSquareLenght-g_dSquareWidth)/2.0 + 5.0;
      ELSIF g_nPipeType = 10 THEN
        dMaxChangeHeight := SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0) + 10.0;
      ELSE 
        dMaxChangeHeight := 0.0;
      END_IF;
    END_IF;

  65:(*上抬*)
    nLayerStartState_bak := 65;
    (*dUpLiftheight:轮廓间上抬高度  dMaxChangeHeight：△上抬距离（安全距离）*)
    IF (Axis_Z.NCTOPLC.ACTPOS + dUpLiftheight + dMaxChangeHeight) <= g_fLiftCoord THEN
      g_fZRelDistance := dUpLiftheight + dMaxChangeHeight;
    ELSIF (Axis_Z.NCTOPLC.ACTPOS + dUpLiftheight + dMaxChangeHeight) > g_fLiftCoord AND (Axis_Z.NCTOPLC.ACTPOS + dMaxChangeHeight) < g_fLiftCoord THEN
      g_fZRelDistance := g_fLiftCoord - Axis_Z.NCTOPLC.ACTPOS;
    ELSIF (Axis_Z.NCTOPLC.ACTPOS + dMaxChangeHeight) >= g_fLiftCoord THEN
      g_fZRelDistance := dMaxChangeHeight;
    END_IF;  

    g_bZRelExecute := TRUE;

    IF g_bZRelDone THEN
      g_bZRelExecute := FALSE;
      nLayerStartState := 70;
    END_IF;
  70:(*开启CNC运动使能*)
    nLayerStartState_bak := 70; 
    g_boCNCMoveDisable := FALSE;
    nLayerStartState := 501;  


  100:(*无感穿孔开光*)
    nLayerStartState_bak := 100;
    g_ugas_type := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Gas;
    g_dmaster_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
    g_dair_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
    g_doxygen_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
    g_dnitogen_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;

    g_bFocusDone := FALSE;
    g_dZoomPosition := g_TechData.multilTechData[nToolNum-1].NoninductivePiercing.dFocusForNoninductivePiercing; 
    g_bFocusEnable := TRUE;  (*通知F轴调焦*)      
    IF g_bgas_enable THEN  (*气是开的忽略开气延时*)
      nLayerStartState := 102;
    ELSE
      g_bgas_enable := TRUE;
      nLayerStartState := 101;
    END_IF;

  101:
   nLayerStartState_bak := 101;
    IF g_bFirstGas THEN(*首吹气延时:*)
      TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(MAX(g_nFirstGasDelayTime,g_nOpenGasDelayTimeAdd))));
      IF TON_FirstGasDelay.Q THEN
        TON_FirstGasDelay(IN :=FALSE);
        g_bFirstGas := FALSE;
        nLayerStartState := 102;
      END_IF;
    ELSE
      TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nOpenGasDelayTimeAdd)));
      IF TON_FirstGasDelay.Q THEN
        TON_FirstGasDelay(IN :=FALSE);
        nLayerStartState := 102;
      END_IF;
    END_IF;  
  102:
     nLayerStartState_bak := 102;
     IF g_bFocusDone THEN
      g_dZFollowSmoothPierceHt := g_TechData.multilTechData[nToolNum-1].NoninductivePiercing.dHeightForNoninductivePiercing;
      g_dZFollowSmoothPierceTime := g_TechData.multilTechData[nToolNum-1].NoninductivePiercing.dTimeForNoninductivePiercing;
      g_dZFollowSmoothCutHt := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Height; 
      g_bZFollowSmoothExecute := TRUE;
      nLayerStartState := 103;
    END_IF;
  103:
     nLayerStartState_bak := 103;
     IF g_bZFollowSmoothPierceStart THEN
      IF g_TechData.multilTechData[nToolNum-1].NoninductivePiercing.bNoninductivePiercingLaserAdjust THEN
         g_nPower := g_TechData.multilTechData[nToolNum-1].NoninductivePiercing.nNoninductivePiercingPower;
        g_nPwmFreq := g_TechData.multilTechData[nToolNum-1].NoninductivePiercing.nNoninductivePiercingFrequency;
        g_nPwmDuty := g_TechData.multilTechData[nToolNum-1].NoninductivePiercing.nNoninductivePiercingDuty;
      ELSE
         g_nPower := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Power));
        g_nPwmFreq := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Frequency));
        g_nPwmDuty := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Duty));
      END_IF;
      g_bLaserCuttingEnable := TRUE;
      nLayerStartState := 104;
     END_IF;
  104:
    nLayerStartState_bak := 104;
    IF g_bZFollowSmoothPierceEnd THEN
      nLayerStartState := 107;
      g_bFocusDone := FALSE;
      g_dZoomPosition := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Focus;
      g_bFocusEnable := TRUE;  (*通知F轴调焦*)
    END_IF;
  105:(*无感穿孔+蛙跳已经开光开气,随动没了,下一步需要开随动即可*)
    nLayerStartState_bak := 105;
    g_fZFollowHeight := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Height;
    g_bZFollowExecute := TRUE;
    nLayerStartState := 106;
  106:
    nLayerStartState_bak := 106;
    g_nFollowState :=42; 
    IF g_bZFollowDone THEN
      g_bZFollowExecute := FALSE;
      nLayerStartState := 440;
      bZHeightJudgeOpen := FALSE;
      g_nPiercingStatus := 0;
     g_foCuttingSpeed := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Speed *1000.0;

    g_nCurCutState :=1;
    g_nPower := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Power));
    g_nPwmFreq := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Frequency));
    g_nPwmDuty := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Duty));

    END_IF;

  107:
     nLayerStartState_bak := 107;
    g_nPiercingStatus := 0;
    g_foCuttingSpeed := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Speed *1000.0;

    g_nCurCutState :=1;
    g_nPower := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Power));
    g_nPwmFreq := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Frequency));
    g_nPwmDuty := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Duty));
    g_fZFollowHeight := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Height;
    g_bSmoothFollowEnable := TRUE;
    nLayerStartState := 420;
  200:(*等级穿孔*)
    nLayerStartState_bak := 200; 
    IF g_TechData.multilTechData[nToolNum-1].NEW_MULTIL_PIERCING[2].bPierEnable THEN
      IF g_TechData.multilTechData[nToolNum-1].NEW_MULTIL_PIERCING[2].Piercing_Height <= g_dZFollowMaxHeight THEN
        g_bZExecuteFollowToBottom := FALSE;
      ELSE
        g_bZExecuteFollowToBottom := TRUE;
      END_IF;
      g_nCurrentCutLevel := 3;
      nLayerStartState := 201;
    ELSIF  g_TechData.multilTechData[nToolNum-1].NEW_MULTIL_PIERCING[1].bPierEnable THEN
     IF g_TechData.multilTechData[nToolNum-1].NEW_MULTIL_PIERCING[1].Piercing_Height <= g_dZFollowMaxHeight THEN
        g_bZExecuteFollowToBottom := FALSE;
      ELSE
        g_bZExecuteFollowToBottom := TRUE;
      END_IF;
      g_nCurrentCutLevel := 2;
      nLayerStartState := 203;

    ELSIF g_TechData.multilTechData[nToolNum-1].NEW_MULTIL_PIERCING[0].bPierEnable THEN
       IF g_TechData.multilTechData[nToolNum-1].NEW_MULTIL_PIERCING[0].Piercing_Height <= g_dZFollowMaxHeight THEN
        g_bZExecuteFollowToBottom := FALSE;
      ELSE
        g_bZExecuteFollowToBottom := TRUE;
      END_IF;
      g_nCurrentCutLevel := 1;
      nLayerStartState := 205;
    END_IF;
  201:(*初始化*)
    FB_LevelCut(
      bInitialize := TRUE,
       bStart := FALSE,
       nLevel := 3,
        bFollowCut := TRUE);
      nLayerStartState := 202;
  202:(*3级穿孔*)
     FB_LevelCut(
     bInitialize := FALSE,
     bStart := TRUE,
     nLevel := 3,
     bFollowCut := TRUE);
     IF FB_LevelCut.bDone THEN
        nLayerStartState := 203; 
        g_bZFollowExecute := FALSE; 
    END_IF;
  203:(*初始化*)
     FB_LevelCut(
      bInitialize := TRUE,
       bStart := FALSE,
       nLevel := 2,
     bFollowCut := TRUE);
      nLayerStartState := 204;
  204:(*2级穿孔*)
     FB_LevelCut(
     bInitialize := FALSE,
     bStart := TRUE,
     nLevel := 2,
     bFollowCut := TRUE);
     IF FB_LevelCut.bDone THEN
        nLayerStartState := 205;
        g_bZFollowExecute := FALSE;  
    END_IF;
  205:(*初始化*)
     FB_LevelCut(
      bInitialize := TRUE,
       bStart := FALSE,
       nLevel := 1,
     bFollowCut := TRUE);
      nLayerStartState := 206;
  206:(*1级穿孔*)
     FB_LevelCut(
     bInitialize := FALSE,
     bStart := TRUE,
     nLevel := 1,
     bFollowCut := TRUE);
     IF FB_LevelCut.bDone THEN
        nLayerStartState := 383; 
        g_bZFollowExecute := FALSE; 

    END_IF; 
  383:(*换气判断*)
    nLayerStartState_bak := 383;
    IF g_ugas_type <> g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Gas AND (g_nToolNum-1)<>6 THEN
      g_bChangeGasFlag := TRUE;
    END_IF;
    nLayerStartState := 390; 
  390:(*换气关气，预穿孔判断*)
    nLayerStartState_bak := 390;
    IF g_bChangeGasFlag THEN  (*换气关气，不换气不关气*)
      g_bgas_enable := FALSE;
    END_IF; 
    nLayerStartState := 400; 

  400:(*切割速度*)
    nLayerStartState_bak := 400;
    g_nPiercingStatus := 0;
    g_foCuttingSpeed := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Speed *1000.0;
    nLayerStartState := 410;
    g_bFocusDone := FALSE;
    g_dZoomPosition := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Focus;
    g_bFocusEnable := TRUE;(*通知F轴调焦*)
    bFocusEnable := TRUE;  
    g_nCurCutState :=1;
     IF g_dOpenFlameTiming = 2 THEN(*关火判断*)
      g_bIgnition := FALSE;(*关火*)
    END_IF;
  410:(*切割出气*)
    nLayerStartState_bak := 410;
    g_ugas_type := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Gas;
    IF bInCornerFalg THEN
		g_dmaster_pressure := g_TechData.multilTechData[nToolNum-1].CornerCompen.dPressure;
		g_dair_pressure := g_TechData.multilTechData[nToolNum-1].CornerCompen.dPressure;
		g_doxygen_pressure := g_TechData.multilTechData[nToolNum-1].CornerCompen.dPressure;
		g_dnitogen_pressure := g_TechData.multilTechData[nToolNum-1].CornerCompen.dPressure;
    ELSE
		g_dmaster_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
		g_dair_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
		g_doxygen_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
		g_dnitogen_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;

      g_dCombustible_pressure :=g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.CombustibleGasPressure;(*可燃气*)  
      g_dOxidizing_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.OxidizingGasPressure;(*助燃气*) 
    END_IF;

    g_bgas_enable := TRUE;
    IF g_bProfileEnable AND NOT g_bProfileFollowEnable THEN(*板外切割：关随动切割*)
      (*g_dProfileAltimetricCompensation : 板外起刀补偿高度：这个补偿作用于在板外关随动情况下进来，避免撞头的问题，默认值0.1*)
      IF g_dProfileCuttingPos = 0.0 THEN
        g_fZAbsPosition := g_dProfileCuttingSimPos + g_dProfileAltimetricCompensation;
      ELSE
        g_fZAbsPosition := g_dProfileCuttingPos + g_dProfileAltimetricCompensation;
      END_IF;
      g_bZAbsExecute := TRUE;  
    ELSE
      g_fZFollowHeight := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Height;
      g_bZFollowExecute := TRUE;
    END_IF;

    IF g_bFirstGas THEN
      IF g_bChangeGasFlag THEN 
        nTimeTemp := g_nFirstGasDelayTime + g_nChangeGasDelayTime;
      ELSE
        nTimeTemp := g_nFirstGasDelayTime;
      END_IF;
    ELSE
      IF g_bChangeGasFlag THEN 
        nTimeTemp := g_nChangeGasDelayTime;
      ELSE
        nTimeTemp := 0;
      END_IF;
    END_IF;
    IF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=0 THEN
      nTimeTemp := nTimeTemp + g_nOpenGasDelayTimeAdd;
    END_IF;
    TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nTimeTemp)));
    IF TON_FirstGasDelay.Q THEN
      TON_FirstGasDelay(IN :=FALSE);
      IF g_bProfileEnable AND NOT g_bProfileFollowEnable THEN(*板外切割：关随动切割*)
        nLayerStartState := 422;
      ELSE
        nLayerStartState := 420;
      END_IF;
    END_IF;

  415:
    nLayerStartState_bak := 415;
    g_ugas_type := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Gas;
    g_dmaster_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
    g_dair_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
    g_doxygen_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
    g_dnitogen_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
    g_bgas_enable := TRUE;
    IF g_bFirstGas THEN
      IF g_bChangeGasFlag THEN 
        nTimeTemp := g_nFirstGasDelayTime + g_nChangeGasDelayTime;
      ELSE
        nTimeTemp := g_nFirstGasDelayTime;
      END_IF;
    ELSE
      IF g_bChangeGasFlag THEN 
        nTimeTemp := g_nChangeGasDelayTime;
      ELSE
        nTimeTemp := g_nOpenGasDelayTimeAdd;
      END_IF;
    END_IF;
    IF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=0 THEN
      nTimeTemp := nTimeTemp + g_nOpenGasDelayTimeAdd;
    END_IF;
    TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nTimeTemp)));
    IF TON_FirstGasDelay.Q THEN

      TON_FirstGasDelay(IN :=FALSE);

      nLayerStartState := 425;

    END_IF;

  420:(*等待切割随动到位*)
    nLayerStartState_bak := 420; 
    g_bChangeGasFlag := FALSE;   (*复位换气标志位*) 
    g_bFirstGas := FALSE;        (*复位首吹气标志位*)
    g_nFollowState :=43; 
    IF g_bZFollowDone THEN
      g_bZFollowExecute := FALSE;
      TON_FirstGasDelay(IN := FALSE);
      nLayerStartState := 430;
      IF g_bProcessHalCloseFollowState THEN
        nLayerStartState := 427;
      END_IF;
      bZHeightJudgeOpen := FALSE;
    END_IF;
  422:(*板外切割：等待切割到位*)
    nLayerStartState_bak := 422; 
    g_bChangeGasFlag := FALSE;   (*复位换气标志位*) 
    g_bFirstGas := FALSE;        (*复位首吹气标志位*)
    IF g_bZAbsDone THEN
      g_bZAbsExecute := FALSE;  
      TON_FirstGasDelay(IN := FALSE);
      nLayerStartState := 430;
    END_IF;
  425:  
    nLayerStartState_bak := 425; 
    g_bChangeGasFlag := FALSE;   (*复位换气标志位*) 
    g_bFirstGas := FALSE;        (*复位首吹气标志位*)
    nLayerStartState := 430; 

  427:(*引脚触发关随动切割，随动下来后，把随动关了*)
    nLayerStartState_bak := 427;
    g_bZFollowClose := TRUE;
    g_nFollowState :=133; 
    IF g_bZFollowOutDone THEN
      g_bZFollowClose := FALSE;
      TON_FirstGasDelay(IN := FALSE);
      nLayerStartState := 430;
    END_IF;
  430:(*切割出光*)
   nLayerStartState_bak := 430;
	IF g_bFocusDone THEN(*调焦完成*)
		IF bInCornerFalg THEN
			g_nPower := DINT_TO_UINT(g_TechData.multilTechData[nToolNum-1].CornerCompen.nPower);
			g_nPwmFreq := DINT_TO_UINT(g_TechData.multilTechData[nToolNum-1].CornerCompen.nHz);
			g_nPwmDuty :=DINT_TO_UINT(g_TechData.multilTechData[nToolNum-1].CornerCompen.nDuty);
		ELSE
			g_nPower := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Power));
			g_nPwmFreq := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Frequency));
			g_nPwmDuty := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Duty));
		END_IF;

        g_bLaserCuttingEnable := TRUE;
         IF g_bProcessHalCloseLaserState THEN(*外部M代码关光标志*)
          g_bLaserCuttingEnable := FALSE;
        END_IF;
        IF g_bLayerStartOffLaser THEN(*轮廓随动不开关标志位,直到引脚开随动将它冲掉*)
          g_bLaserCuttingEnable := FALSE;
        END_IF; 
        IF bStratAfterPause THEN
          StratAfterPauseLightDelayTime_TON(IN := TRUE,PT := LREAL_TO_TIME(FUN_MSTOS(nStratAfterPauseLightDelayTime)));
          IF StratAfterPauseLightDelayTime_TON.Q THEN
            StratAfterPauseLightDelayTime_TON(IN := FALSE);
            bStratAfterPause := FALSE;
            nLayerStartState := 440;
          END_IF;
        ELSE
          nLayerStartState := 440;
        END_IF;  
    END_IF;
  440:(*开启NC运动使能*)
    nLayerStartState_bak := 440;
    TON_PreCutDelay(IN:=TRUE,PT :=LREAL_TO_TIME(FUN_MStoS(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_PreCutDelay)));
    IF TON_PreCutDelay.Q THEN(*预切割延时：延时完成开始NC运动*)
      TON_PreCutDelay(IN :=FALSE);
      g_boCNCMoveDisable := FALSE;
      nLayerStartState := 500;
    END_IF;   
  500:(*切割中*)
    nLayerStartState_bak := 500;
    g_foCuttingSpeed := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Speed *1000.0;
    nLayerStartState := 500;
    g_nCurCutState :=1;
  501:(*板外切割 第二阶段 空行中*)
    nLayerStartState_bak := 501;
    g_foCuttingSpeed := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Speed *1000.0;
    nLayerStartState := 501;
    g_nCurCutState :=0;
  600:(*和速度为0*)
    IF g_fiXYUCurrentSpeed<=0.001 THEN
      nLayerStartState := 601;
    END_IF;
  601:
    (*暂停-关光关气*)
    IF g_bDryRunEnable OR g_bDebugMode THEN
      nLayerStartState := 602;
    ELSE
      IF g_bLaserCuttingEnable THEN
        TON_PauseStopLaserDelay(IN:=TRUE,PT :=LREAL_TO_TIME(FUN_MStoS(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_PauseStopLaserDelay)));
        IF TON_PauseStopLaserDelay.Q THEN(*暂停关光延时*)
          TON_PauseStopLaserDelay(IN :=FALSE);
          g_bLaserCuttingEnable := FALSE;
          bCloseGasDelayEnable := TRUE;
          g_bgas_enable := FALSE;
          nLayerStartState := 602;
        END_IF;
      ELSE
        g_bgas_enable := FALSE;
        g_bLaserCuttingEnable := FALSE;
        bCloseGasDelayEnable := TRUE;
        nLayerStartState := 602;
      END_IF;
    END_IF;
  602: 
    g_bZLiftExecute := FALSE;
    IF Axis_Z.NCTOPLC.AXISSTATE = 2 THEN
      nLayerStartState := 610;
    ELSIF Axis_Z.NCTOPLC.AXISSTATE = 9 THEN
      g_bZFollowClose := TRUE;
      nLayerStartState := 605;
    END_IF;
  605:
    g_nFollowState :=134;
    IF g_bZFollowOutDone THEN
      nLayerStartState := 610;
      g_bZFollowClose := FALSE;
    END_IF;
  610:
    (*遇到某些不需要上抬的情况，直接进入下一个状态机，否则上抬*)
    IF g_bDryRunEnable OR bLookBackEnable OR g_bDebugMode THEN
      nLayerStartState := 620;
    ELSE
      g_bZLiftExecute := TRUE;
    END_IF;
    IF g_bZLiftingDone THEN
      g_bZLiftExecute := FALSE;
      nLayerStartState := 620;
    END_IF;
  620:(*暂停*)
    IF nLayerStartState_bak=0 THEN
      nLayerStartState := 0;
    ELSIF bLookBackEnable OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack  THEN
      nLayerStartState := 0;
      g_boCNCMoveDisable := FALSE;
      bLookBackDone := TRUE;
      g_bAutoExecuteFallBack := FALSE;
    ELSIF bCurState AND (g_bDryRunEnable OR g_bDebugMode) THEN
      nLayerStartState := 500;
      g_boCNCMoveDisable := FALSE;
    ELSIF bCurState AND nLayerStartState_bak>=400 THEN
      IF nLayerStartState_bak >=440 THEN
        bStratAfterPause := TRUE; 
      END_IF;
      IF g_bRapidContinue OR g_bHmiCloseFollow THEN(*快速继续就是继续,继续才是重走一次*)
         nLayerStartState := 400;
        g_bRapidContinue := FALSE;
        g_bHmiCloseFollow := FALSE;
      ELSE
		 nLayerStartState := 9;
         IF g_niFllowStatusFromCNC = 1 OR g_bProfileEnable THEN
           nLayerStartState := 400;
         END_IF;
      END_IF;
      g_boCNCMoveDisable := TRUE;
    ELSIF bCurState AND nLayerStartState_bak<400 THEN
      nLayerStartState := 9;
    END_IF;
END_CASE;

CASE nLayerEndState OF
  0:(*空闲*)
    nLayerEndState_bak := 0;
    nLayerEndState := 0;
    WaitTimeOut(IN := FALSE);
  10:(*关闭CNC运动使能*)
    nLayerEndState_bak := 10;
    g_boCNCMoveDisable := TRUE;
    nLayerEndState := 100;
    bInCornerFalg := FALSE;
  100:(*关闭切割关光*)
    nLayerEndState_bak := 100;
    Timer_LayerEndStopLightTime(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nLayerEndStopLight_Time)));
    IF Timer_LayerEndStopLightTime.Q THEN
      Timer_LayerEndStopLightTime(IN := FALSE);
      g_bLaserCuttingEnable := FALSE;
      g_nCurCutState :=0;
      g_bIgnition := FALSE;(*关火*)
      (*型材切割有可能会出现未开随动轮廓结束，所以执行Layer_End，如果发现不在随动状态，直接跳过关随动状态机*)
      IF Axis_Z.NCTOPLC.AxisState = 9 THEN
        nLayerEndState := 110;
      ELSE
        bCloseGasDelayEnable := TRUE;
        nLayerEndState := 200;
      END_IF;
    END_IF;
  110:(*关闭切割关气，关随动*)
    nLayerEndState_bak := 110;
    bCloseGasDelayEnable := TRUE;
    g_bZFollowExecute := FALSE;
    g_bZFollowClose := TRUE;
    g_nFollowState :=140;
    IF g_bZFollowOutDone THEN
      (*如果是微连的话，不需要进入111，直接进入上抬判断*)
      IF LREAL_TO_INT(g_fMicroConnectEnableM) = 1 THEN
        nLayerEndState := 200;
        g_boClaw3UpLiftDone := TRUE;
      ELSIF g_nMachineType = 6 THEN
        nLayerEndState := 111;
      ELSIF g_nMachineType = 9 THEN
        nLayerEndState := 130;
      ELSE
        nLayerEndState := 200;
      END_IF;
      g_bZFollowClose := FALSE;
      IF g_bRealTimeCAlibrateStarting THEN
        g_bRealTimeCAlibrateStarting := FALSE;
        g_bZLiftExecute := TRUE;
        nLayerEndState := 307;
      END_IF;
    END_IF;
    (*开启了无感穿孔提前调焦*)
    IF g_TechData.multilTechData[g_dNextToolNum-1].NoninductivePiercing.bOpen THEN
      g_nPower := g_TechData.multilTechData[g_dNextToolNum-1].NoninductivePiercing.nNoninductivePiercingPower;      
      g_nPwmFreq := g_TechData.multilTechData[g_dNextToolNum-1].NoninductivePiercing.nNoninductivePiercingFrequency;
      g_nPwmDuty := g_TechData.multilTechData[g_dNextToolNum-1].NoninductivePiercing.nNoninductivePiercingDuty;
      g_bFocusDone := FALSE;
      g_dZoomPosition := g_TechData.multilTechData[g_dNextToolNum-1].NoninductivePiercing.dFocusForNoninductivePiercing;
      g_bFocusEnable := TRUE;
    END_IF;
  111:
    nLayerEndState_bak := 111;
    g_boCNCMoveDisable := TRUE;

    IF bUpLiftFlag OR (g_dNestingDistanceToGoM = 0.0 AND g_dNestingMotionAngleM = 0.0) THEN
      IF Axis_Z.NCTOPLC.ACTPOS > (g_fLiftCoord - 1.0) THEN
        nLayerEndState := 600;
        g_boCNCMoveDisable := FALSE;
      ELSE
        nLayerEndState := 200;
      END_IF;
    ELSIF bClaw3UpLiftFlag THEN
      IF Axis_Z.NCTOPLC.ACTPOS >= (g_fLiftCoord - 1.0) THEN
        nLayerEndState := 120;
      ELSE
        g_bZRelExecute := FALSE;
        nLayerEndState := 115;
      END_IF;
    END_IF;
  115:
    nLayerEndState_bak := 115;
    g_bZRelExecute := TRUE;
    g_fZRelDistance := dUpLiftheight;
    IF g_bZRelDone THEN
      g_bZRelExecute := FALSE;
      g_boClaw3UpLiftDone := TRUE;
      nLayerEndState := 120;
    END_IF;
  120:
    nLayerEndState_bak := 120;
    g_boClaw3UpLiftDone := TRUE;

    IF bUpLiftFlag THEN
      IF Axis_Z.NCTOPLC.ACTPOS > (g_fLiftCoord - 1.0) THEN
        nLayerEndState := 600;
        g_boCNCMoveDisable := FALSE;
      ELSE
        nLayerEndState := 200;
      END_IF;
    END_IF;
  130:
    g_boCNCMoveDisable := FALSE;
    IF g_boBoendeCheckDone THEN
      g_boCNCMoveDisable := TRUE;
      nLayerEndState := 200;
    END_IF;
  200:(*判断是否蛙跳*)
    nLayerEndState_bak := 200;
    g_bZLiftExecute := FALSE;
    (*没有蛙跳，直接上抬*)
    IF bFrogLeapEnable AND (g_dNestingDistanceToGoM <> 0.0 OR g_dNestingMotionAngleM <> 0.0) THEN(*当下个零件剩余角度和距离都为0时，确认已经是最后一个轮廓了，不蛙跳。*)
      nLayerEndState := 400;(*执行蛙跳*)
      IF g_dNestingIsUseSideCenterM<>0.0 OR g_dNestingIsPullerM = 1.0 THEN(*下个轮廓执行分中的话，就不执行蛙跳了,下个轮廓要拉料的话也不要蛙跳*)
        nLayerEndState := 300;(*直接上抬*) 
      END_IF;
    ELSE
      nLayerEndState := 300;(*直接上抬*) 
    END_IF;
    IF bFrogLeapEnable AND g_bClaw2Aoiding THEN(*当前情况是当卡盘避让和蛙跳同时执行时，蛙跳上台而cnc未运动，Z轴重新上台到轮廓高度，确保管子不碰到切割头*)
      g_bClaw2Aoiding := FALSE;
      nLayerEndState := 300;(*直接上抬*)
    END_IF;
    (*根据不同管型，获取△上抬距离（安全距离） pipetype: 0、平面 1、圆 2、矩形 3、腰 4、椭圆 5、D型管 10、H钢 11、角钢*)
    dXCoordToCenter := ABS(g_diXMachineCoordinate - g_dBeamCenterPos);(*X轴当前坐标距离X轴中心的距离*)
    IF g_nPipeType = 1 THEN 
      IF dXCoordToCenter >= 0.5 THEN(*判断是平面孔情况的还是空间孔情况*) 
         (*如果轮廓跳转时检测到X轴不在中心位置，需要上抬保证安全*)
         dCircleLiftTemp := SQRT(g_dCircleRadius*g_dCircleRadius - dXCoordToCenter*dXCoordToCenter);
         dMaxChangeHeight := g_dCircleRadius - dCircleLiftTemp + 1.0;
      ELSE
        dMaxChangeHeight := 0.0; 
      END_IF;
    ELSIF g_nPipeType = 2 OR g_nPipeType = 11 THEN
      dMaxChangeHeight := SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0) + 5.0;
      dPipeHalfValue := MAX(g_dSquareLenght,g_dSquareWidth)/2.0;
    ELSIF g_nPipeType = 3 OR g_nPipeType = 4 THEN  
      dMaxChangeHeight := (g_dSquareLenght-g_dSquareWidth)/2.0 + 5.0;
       dPipeHalfValue := MAX(g_dSquareLenght,g_dSquareWidth)/2.0;
    ELSIF g_nPipeType = 10 THEN
      dMaxChangeHeight := SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0) + 5.0;
      dPipeHalfValue := SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0) + 10.0;
     ELSIF g_nPipeType = 12 THEN
       dMaxChangeHeight := SQRT(g_dBoundRectangleWidth*g_dBoundRectangleWidth/4.0 + g_dBoundRectangleheight*g_dBoundRectangleheight/4.0) + 5.0; 
     dPipeHalfValue := SQRT(g_dBoundRectangleWidth*g_dBoundRectangleWidth/4.0 + g_dBoundRectangleheight*g_dBoundRectangleheight/4.0) + 10.0; 
    ELSE(*对于未做蛙跳处理的管型，默认不蛙跳，比如椭圆管，腰管*) 
      dMaxChangeHeight := 0.0;
      nLayerEndState := 300;
    END_IF;
    IF g_bOffSiteCloseFrogFlagM THEN
      nLayerEndState := 300;
      g_bOffSiteCloseFrogFlagM := FALSE;
    END_IF;
    IF (g_nPipeType = 1 OR g_dNestingMotionAngleM = 0.0) AND (g_dNestingDistanceToGoM <> 0.0 OR g_dNestingMotionAngleM <> 0.0) THEN
      IF g_bNotLiftForShortDistanceEnable AND g_dNestingDistanceToGoM <= g_dNotLiftForShortDistance THEN (*同面或者圆管开启了短距离不抬刀且下个轮廓移动距离小于设置的不抬刀距离则不上抬*)
          g_boCNCMoveDisable := FALSE; 
          nLayerEndState := 600;
      END_IF;
    END_IF;

  300:(*不蛙跳上抬*)
    nLayerEndState_bak := 300;
    IF g_dNestingDistanceToGoM=0.0 AND g_dNestingMotionAngleM=0.0 AND g_bNestingIsPartEnd THEN (*判断下个轮廓的移动距离和角度同时为0即为程序结束直接上抬到最高点*)
      g_bZLiftExecute := TRUE;
      nLayerEndState := 307;
    ELSIF (Axis_Z.NCTOPLC.ACTPOS + dUpLiftheight + dMaxChangeHeight) <= g_fLiftCoord THEN
      (*dUpLiftheight:轮廓间上抬高度  dMaxChangeHeight：△上抬距离（安全距离）*)
       g_fZRelDistance := dUpLiftheight + dMaxChangeHeight;
       nLayerEndState := 305;
       g_bZRelExecute := FALSE;
       g_bZRelDone := FALSE;
    ELSE
      g_bZLiftExecute := TRUE;
      nLayerEndState := 307;
    END_IF; 
  305:
    g_bZRelExecute := TRUE;
    IF g_bZRelDone THEN
      g_bZRelExecute := FALSE;
      nLayerEndState := 310;
    END_IF;
  307:
    nLayerEndState_bak := 307;
    IF g_bZLiftingDone THEN
      nLayerEndState := 310;
      g_bZLiftExecute := FALSE;
    END_IF;
  310:(*不蛙跳：开启CNC运动使能  在分中,避让等下不提前吹气,320去提前吹气*)
    nLayerEndState_bak := 310; 
    g_boCNCMoveDisable := FALSE;
    nLayerEndState := 600;
    IF g_TechData.multilTechData[nToolNum-1].NoninductivePiercing.bOpen THEN (*无感穿孔特殊处理*)
      g_bgas_enable := FALSE;
    END_IF;

  400:
     nLayerEndState_bak := 400;
    (*pipetype: 0、平面 1、圆 2、矩形 3、腰 4、椭圆 5、D型管 10、H钢 11、角钢*)
    IF g_nPipeType = 1 THEN  (*圆管随便跳*) 
        nLayerEndState := 500;
        bFropLeapType := 1;
    ELSE(*判断是不是在同一面蛙跳*)
      IF g_dNestingMotionAngleM = 0.0 THEN(*蛙跳到同一面*) 
        bFropLeapType := 1;
        IF g_nPipeType <>  12 THEN
          dMaxChangeHeight := 0.0;
        END_IF;
        nLayerEndState := 500;(*无安全隐患，直接蛙跳*) 
      ELSE(*蛙跳到另一面*)
        IF g_dNestingDistanceToGoM = 0.0 THEN
          bFropLeapType := 2;
        ELSE
          bFropLeapType := 3;
        END_IF ;  
        nLayerEndState := 500;
      END_IF;
    END_IF;

  500:(*蛙跳前：计算避让上抬安全高度*) 
    nLayerEndState_bak := 500;
    g_fZleapHeight_temp := g_fZleapHeight;
    IF Axis_Z.NCTOPLC.ACTPOS  >= g_fLiftCoord THEN
      dTempHeight := 0.0;  
    ELSE
      IF Axis_Z.NCTOPLC.ACTPOS + dUpLiftheight+ dMaxChangeHeight >= g_fLiftCoord THEN
        dTempHeight := g_fLiftCoord - Axis_Z.NCTOPLC.ACTPOS;
      ELSE
        dTempHeight := dUpLiftheight+ dMaxChangeHeight;
      END_IF;
      IF bFropLeapType <> 1 OR g_bProfileEndDone THEN
        IF g_fZleapHeight < dPipeHalfValue THEN
          g_fZleapHeight_temp := dPipeHalfValue;
        END_IF;
        g_bProfileEndDone := FALSE;
      END_IF;
    END_IF;

    IF Axis_Z.NCTOPLC.ACTPOS + g_fZleapHeight_temp >= g_fLiftCoord THEN
		g_fZleapHeight_temp := g_fLiftCoord - Axis_Z.NCTOPLC.ACTPOS;
    END_IF;
    g_bZLeapForgEnable := TRUE;
    g_fZLeapUpHeight := dTempHeight;
    IF g_TechData.multilTechData[g_dNextToolNum-1].NoninductivePiercing.bOpen THEN
      g_fZLeapDownHeight := g_TechData.multilTechData[g_dNextToolNum-1].NoninductivePiercing.dHeightForNoninductivePiercing;
      g_fZLeapCutHeight := g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.fCutting_Height;
      g_fZLeapPierceTime := g_TechData.multilTechData[g_dNextToolNum-1].NoninductivePiercing.dTimeForNoninductivePiercing;
      IF g_diG00Time < 0.2 THEN
         g_ugas_type := g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.nCutting_Gas;
         g_dmaster_pressure := g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
         g_dair_pressure := g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
         g_doxygen_pressure := g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
         g_dnitogen_pressure := g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
         g_bgas_enable := TRUE;
         bCloseGasDelayEnable := FALSE; (*复位关气延时*)  
      END_IF;
    ELSIF g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[0].bPierEnable THEN
      for indx := 2 to 0 BY -1 DO
            IF g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[indx].bPierEnable THEN        
              IF g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[indx].Piercing_Height <= g_dZFollowMaxHeight THEN
                g_fZLeapDownHeight := g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[indx].Piercing_Height;
              ELSE
                g_fZLeapDownHeight := 1.0;
              END_IF;
              g_fZLeapCutHeight := g_fZLeapDownHeight;
              g_fZLeapPierceTime := 0.0;
              exit;(*退出循环*)
            end_if;
         end_for;     
    ELSE
      IF g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.fCutting_Height <= g_dZFollowMaxHeight THEN
        g_fZLeapDownHeight := g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.fCutting_Height;
      ELSE
        g_fZLeapDownHeight := 1.0;
      END_IF;
      g_fZLeapCutHeight := g_fZLeapDownHeight; 
      g_fZLeapPierceTime := 0.0;

    END_IF;
    IF g_diG00Time <0.001 THEN   (*G00总时间等于0时,强制给0.001,用于起点终点同一个位置的情况下,蛙跳报错*)
        g_fZLeapTime_rem := 0.001; (*给个假蛙跳时间*) 
    ELSE
        g_fZLeapTime_rem := g_diG00Time; (*蛙跳时间*)
    END_IF;  
    nLayerEndState := 520; 
    Ton_wait1(IN :=FALSE);
  520:
    nLayerEndState_bak := 520; 
    IF g_bZLeapDone THEN
      g_boCNCMoveDisable := FALSE;
      IF g_diG00Time < 0.001 THEN
       g_fZLeapTime_rem := g_diG00Time_rem; 
       nLayerEndState := 525;               
      ELSIF g_diG00Time_rem < 0.001 THEN   (*延时等待g_diG00Time_rem拿到距离数据*)
        Ton_wait1(IN := TRUE,PT := T#100ms); 
        IF Ton_wait1.Q THEN
          Ton_wait1(IN :=FALSE);
          g_fZLeapTime_rem := g_diG00Time_rem; 
          nLayerEndState := 530;
          g_bWaitG00Time_remTimeOutAlarm := TRUE;
        END_IF;
      ELSE
      g_fZLeapTime_rem := g_diG00Time_rem; 
       Ton_wait1(IN :=FALSE); 
       nLayerEndState := 530;
      END_IF;
    END_IF; 
  521:(*关闭蛙跳*)
    nLayerEndState_bak := 521;
    g_ZLeapFrog.EXECUTE := FALSE;
    g_ZMoveStop.EXECUTE := TRUE;
    IF g_ZMoveStop.DONE THEN
      g_ZMoveStop.EXECUTE := FALSE;
       nLayerEndState := 600;
    END_IF;


  530:(*等待蛙跳完成*)
    nLayerEndState_bak := 530;
    IF g_diG00Time_rem <=FUN_MSTOS(LREAL_TO_DINT(g_dG00OpenGasTime))+0.001  THEN (*蛙跳空行剩余时间小于设置值出气*)
      IF g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[0].bPierEnable THEN
        for indx := 2 to 0 BY -1 DO
          if (g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[indx].bPierEnable) then
            g_ugas_type := g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[indx].Piercing_Gas;
            g_dmaster_pressure := g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[indx].Piercing_Gas_Pressure;
            g_dair_pressure := g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[indx].Piercing_Gas_Pressure;
            g_doxygen_pressure := g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[indx].Piercing_Gas_Pressure;
            g_dnitogen_pressure := g_TechData.multilTechData[g_dNextToolNum-1].NEW_MULTIL_PIERCING[indx].Piercing_Gas_Pressure;
            EXIT;(*退出循环*)
          end_if;
        end_for;
      ELSE
        g_ugas_type := g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.nCutting_Gas;
        g_dmaster_pressure := g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
        g_dair_pressure := g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
        g_doxygen_pressure := g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
        g_dnitogen_pressure := g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      END_IF;  
      g_bgas_enable := TRUE;
      bCloseGasDelayEnable := FALSE; (*复位关气延时*)       
    END_IF; 
    IF g_TechData.multilTechData[g_dNextToolNum-1].NoninductivePiercing.bOpen AND g_bZLeapFrogPierceStart THEN
      IF g_TechData.multilTechData[g_dNextToolNum-1].NoninductivePiercing.bNoninductivePiercingLaserAdjust THEN
        g_nPower := g_TechData.multilTechData[g_dNextToolNum-1].NoninductivePiercing.nNoninductivePiercingPower;
        g_nPwmFreq := g_TechData.multilTechData[g_dNextToolNum-1].NoninductivePiercing.nNoninductivePiercingFrequency;
        g_nPwmDuty := g_TechData.multilTechData[g_dNextToolNum-1].NoninductivePiercing.nNoninductivePiercingDuty;
      ELSE
        g_nPower := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.nCutting_Power));
        g_nPwmFreq := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.nCutting_Frequency));
        g_nPwmDuty := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.nCutting_Duty));
      END_IF;
      g_bLaserCuttingEnable := TRUE; 
      g_bFocusDone := FALSE;
      g_dZoomPosition := g_TechData.multilTechData[g_dNextToolNum-1].NoninductivePiercing.dFocusForNoninductivePiercing;
      g_bFocusEnable := TRUE;  (*通知F轴调焦,只执行一个周期*)
      nLayerEndState := 535; 
    END_IF;
    IF g_bZLeapForgDone THEN
      nLayerEndState := 600; 
    END_IF;
    IF g_bIsM202Triggered THEN
      g_bIsM202Triggered :=FALSE;
      g_bgas_enable := FALSE;
      g_bLaserCuttingEnable := FALSE;
      nLayerEndState := 521;
      M.ENABLE[202] := 0;
    END_IF;  
    g_fZLeapTime_rem := g_diG00Time_rem; (*蛙跳时间*)

  535:(*蛙跳上抬中*)
    nLayerEndState_bak := 535;
    g_fZLeapTime_rem := g_diG00Time_rem; (*蛙跳时间*)
    IF g_bZLeapForgDone THEN    
      nLayerEndState := 600;     
    END_IF;  
  600:(*LayerEnd完成*)(*用于layerStart中等其结束防止异常结束,建议采集高电平*)
    nLayerEndState_bak := 600;
    g_boLayerEndDone := TRUE;
    g_boClaw3UpLiftDone := TRUE;
    g_dNestingDistanceToGoM := 0.0;
    g_dNestingMotionAngleM := 0.0;
    g_dNestingIsUseSideCenterM := 0.0;
    nLayerEndState := 601;
  601:
    nLayerEndState_bak := 601;

    nLayerEndState := 601;
  700:(*暂停*)
    g_bZLiftExecute := FALSE;
    IF Axis_Z.NCTOPLC.AXISSTATE = 9 AND NOT g_bOpenFollowMFlag THEN
      g_bZFollowClose := TRUE; 
    END_IF;
    IF Axis_Z.NCTOPLC.AXISSTATE = 2 THEN
      nLayerEndState := 710;
      g_bZFollowClose := FALSE;
       g_bZLiftExecute := FALSE;
    END_IF;
  710:
    IF g_bDryRunEnable OR bLookBackEnable OR g_bDebugMode OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack OR
      g_bHMIStartExecuteSideCenterM THEN
      nLayerEndState := 720;
    ELSE
      g_bZLiftExecute := TRUE;
    END_IF;
    IF g_bZLiftingDone THEN
      g_bZLiftExecute := FALSE;
      nLayerEndState := 720;
    END_IF;
  720:
    IF nLayerEndState_bak=0 THEN
      nLayerEndState := 0;
    ELSIF bLookBackEnable  OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack  THEN
      g_boCNCMoveDisable := FALSE;
      nLayerEndState := 0;
      bLookBackDone := TRUE;
      g_boLayerEndDone := TRUE;
      g_bAutoExecuteFallBack := FALSE;
    ELSIF bCurState THEN
      IF g_bDryRunEnable OR g_bDebugMode THEN
        g_boCNCMoveDisable := FALSE;
        nLayerEndState := 600;
      ELSIF g_nMachineType = 6 THEN
        nLayerEndState := 111;
        g_boCNCMoveDisable := FALSE;
      ELSIF bFrogLeapEnable AND (g_dNestingDistanceToGoM <> 0.0 OR g_dNestingMotionAngleM <> 0.0) THEN
        IF nLayerEndState_bak > 520 THEN
          Ton_wait1(IN :=FALSE);
          nLayerEndState := 600;
        ELSE
          nLayerEndState := 400;
        END_IF;
        IF g_dNestingIsUseSideCenterM<>0.0 OR g_dNestingIsPullerM = 1.0 THEN
          nLayerEndState := 310;
        END_IF;
       g_boCNCMoveDisable := FALSE;
      ELSIF nLayerEndState_bak=601 THEN
        nLayerEndState := 601;
        g_boCNCMoveDisable := FALSE;
      ELSE
       nLayerEndState := 310;
      END_IF;
    END_IF;
END_CASE;
IF g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.bCuttingLongBlows AND (nLayerStartState <> 0 OR nLayerEndState <> 0) AND g_nPlcState = 1  AND 
  NOT (g_bDryRunEnable OR g_bDebugMode OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack OR g_bForwardStatusFb) THEN
  g_bgas_enable := TRUE;
ELSIF nLayerStartState = 0 AND nLayerEndState = 0 AND NOT g_bManualOpenGas  THEN 
  g_bgas_enable := FALSE;
END_IF;
Rtring_ZProtect(CLK := bZHeightJudgeOpen);(*高度再判断一个随动误差*)
Ftring_ZProtect(CLK := bZHeightJudgeOpen);
IF Ftring_ZProtect.Q THEN
  nZProtectstate := 0;
  g_bZHeightJudgeOpen := FALSE;
END_IF;
IF Rtring_ZProtect.Q THEN
   IF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=0 THEN (*直接切割，卡盘中心高度-G00Z高度 - 切割高度*)
      nZProtectstate := 20;
    ELSIF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=1 THEN(*穿孔，卡盘中心高度-G00Z高度 - 穿孔高度*)
      nZProtectstate := 100;
    ELSIF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=2 THEN
      nZProtectstate := 200;
    ELSIF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=3 THEN
      nZProtectstate := 300;
    END_IF;
    IF g_bLayerStartOffLaser THEN(*不开光切割，穿孔就跳过了*)
      nZProtectstate := 20;
    END_IF;
END_IF;
IF NOT g_bFollowprotectOPen THEN
  nZProtectstate := 0;
END_IF;
CASE nZProtectstate OF
  0:
    nZProtectstate := 0;
  20:
    dDecelerationdistance := ABS (FUN_DISTANCECALC(0.0,g_fZVelocity,g_dZAxisAcceleration,g_dRunCycleNum));
     IF g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Height <= g_dZFollowMaxHeight THEN (*直接切割高度小于随动最大高度，直接到切割高度*)  
        IF ABS(g_fZCoordinate) + dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Height - g_dZHeightJudgeError THEN
          g_bZHeightJudgeOpen := TRUE;
          nZProtectstate := 0;
          g_bZFollowClose :=TRUE;
          g_bgas_enable := FALSE;
          g_bZFollowExecute :=FALSE;
        END_IF;
      ELSE
        IF ABS(g_fZCoordinate)+ dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - 1.0 - g_dZHeightJudgeError THEN
          g_bZHeightJudgeOpen := TRUE;
          nZProtectstate := 0;
          g_bZFollowClose :=TRUE;
          g_bgas_enable := FALSE;
          g_bZFollowExecute :=FALSE;
        END_IF;
     END_IF;
  100:
    dDecelerationdistance := ABS(FUN_DISTANCECALC(0.0,g_fZVelocity,g_dZAxisAcceleration,g_dRunCycleNum));
    IF g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Height <= g_dZFollowMaxHeight THEN (*普通穿孔高度<随动最高高度,直接随动到位*)
      IF ABS(g_fZCoordinate)+ dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Height - g_dZHeightJudgeError THEN
          g_bZHeightJudgeOpen := TRUE;
          nZProtectstate := 0;
          g_bZFollowClose :=TRUE;
          g_bgas_enable := FALSE;
          g_bZFollowExecute :=FALSE;
        END_IF;
    ELSE
       IF ABS(g_fZCoordinate)+ dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - 1.0 - g_dZHeightJudgeError THEN
          g_bZHeightJudgeOpen := TRUE;
          nZProtectstate := 0;
          g_bZFollowClose :=TRUE;
          g_bgas_enable := FALSE;
          g_bZFollowExecute :=FALSE;
        END_IF;
    END_IF;
  200:(*渐进穿孔*)
  dDecelerationdistance := ABS(FUN_DISTANCECALC(0.0,g_fZVelocity,g_dZAxisAcceleration,g_dRunCycleNum));
      IF g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.bBurstingHole_Enable THEN
        IF g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Height <= g_dZFollowMaxHeight THEN (*爆孔高度<随动最高高度,直接随动到爆孔位置*)
          IF ABS(g_fZCoordinate)+dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Height - g_dZHeightJudgeError THEN
            g_bZHeightJudgeOpen := TRUE;
            nZProtectstate := 0;
            g_bZFollowClose :=TRUE;
            g_bgas_enable := FALSE;
            g_bZFollowExecute :=FALSE;
          END_IF;
        ELSE
           IF ABS(g_fZCoordinate)+dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - 1.0 - g_dZHeightJudgeError THEN
            g_bZHeightJudgeOpen := TRUE;
            nZProtectstate := 0;
            g_bZFollowClose :=TRUE;
            g_bgas_enable := FALSE;
            g_bZFollowExecute :=FALSE;
          END_IF;
        END_IF;
      ELSE
        IF g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Height <= g_dZFollowMaxHeight THEN (*爆孔高度<随动最高高度,直接随动到爆孔位置*)
          IF ABS(g_fZCoordinate)+dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Height - g_dZHeightJudgeError THEN
            g_bZHeightJudgeOpen := TRUE;
            nZProtectstate := 0;
            g_bZFollowClose :=TRUE;
            g_bgas_enable := FALSE;
            g_bZFollowExecute :=FALSE;
          END_IF;
        ELSE
           IF ABS(g_fZCoordinate)+dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - 1.0 - g_dZHeightJudgeError THEN
            g_bZHeightJudgeOpen := TRUE;
            nZProtectstate := 0;
            g_bZFollowClose :=TRUE;
            g_bgas_enable := FALSE;
            g_bZFollowExecute :=FALSE;
          END_IF;
        END_IF;
      END_IF;
  300:(*多级穿孔*)
     IF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.bPierEnable THEN
      nZProtectstate := 314;
    ELSIF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.bPierEnable THEN
      nZProtectstate := 334;
    ELSIF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_LOW.bPierEnable THEN
      nZProtectstate := 365;
    END_IF; 
  314:
  dDecelerationdistance := ABS(FUN_DISTANCECALC(0.0,g_fZVelocity,g_dZAxisAcceleration,g_dRunCycleNum));
    IF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.Mulitil_Piercing_Height <= g_dZFollowMaxHeight THEN
        IF ABS(g_fZCoordinate)+dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.Mulitil_Piercing_Height - g_dZHeightJudgeError THEN
          g_bZHeightJudgeOpen := TRUE;
          nZProtectstate := 0;
          g_bZFollowClose :=TRUE;
          g_bgas_enable := FALSE;
          g_bZFollowExecute :=FALSE;
        END_IF;
    ELSE
       IF ABS(g_fZCoordinate)+dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - 1.0 - g_dZHeightJudgeError THEN
          g_bZHeightJudgeOpen := TRUE;
          nZProtectstate := 0;
          g_bZFollowClose :=TRUE;
          g_bgas_enable := FALSE;
          g_bZFollowExecute :=FALSE;
        END_IF;
    END_IF;
  334:
  dDecelerationdistance := ABS(FUN_DISTANCECALC(0.0,g_fZVelocity,g_dZAxisAcceleration,g_dRunCycleNum));
    IF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.Mulitil_Piercing_Height <= g_dZFollowMaxHeight THEN
      IF ABS(g_fZCoordinate)+dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.Mulitil_Piercing_Height - g_dZHeightJudgeError THEN
          g_bZHeightJudgeOpen := TRUE;
          nZProtectstate := 0;
          g_bZFollowClose :=TRUE;
          g_bgas_enable := FALSE;
          g_bZFollowExecute :=FALSE;
        END_IF;
    ELSE
        IF ABS(g_fZCoordinate)+dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - 1.0 - g_dZHeightJudgeError THEN
          g_bZHeightJudgeOpen := TRUE;
          nZProtectstate := 0;
          g_bZFollowClose :=TRUE;
          g_bgas_enable := FALSE;
          g_bZFollowExecute :=FALSE;
        END_IF;
    END_IF;
END_CASE;
(*判断当前高度是否大于卡盘中心-当前管面的高度*)
IF g_bZHeightJudgeOpen AND Axis_Z.NcToPlc.AXISSTATE = 9 AND g_bFollowprotectOPen THEN
  g_Alarm.alarmArray[390] := 1118;
END_IF;
(*拐角*)
IF RTrigger_Corner_in.Q THEN
  bInCornerFalg := TRUE;
  g_bLaserOnCornerM := FALSE;
  dPressure_note := g_dmaster_pressure;
  nPower_note := g_nPower;
  dAirPressure_note := g_dair_pressure;
  dOxygenPressure_note := g_doxygen_pressure;
  dNirtogenPressure_note := g_dnitogen_pressure;
  nPwmFreq_note := g_nPwmFreq;
  nPwmDuty_note := g_nPwmDuty;
  g_dmaster_pressure := g_TechData.multilTechData[nToolNum-1].CornerCompen.dPressure;
  g_dair_pressure := g_TechData.multilTechData[nToolNum-1].CornerCompen.dPressure;
  g_doxygen_pressure := g_TechData.multilTechData[nToolNum-1].CornerCompen.dPressure;
  g_dnitogen_pressure := g_TechData.multilTechData[nToolNum-1].CornerCompen.dPressure;
  g_nPower := DINT_TO_UINT(g_TechData.multilTechData[nToolNum-1].CornerCompen.nPower);
  g_nPwmFreq := DINT_TO_UINT(g_TechData.multilTechData[nToolNum-1].CornerCompen.nHz);
  g_nPwmDuty :=DINT_TO_UINT(g_TechData.multilTechData[nToolNum-1].CornerCompen.nDuty);
END_IF;
IF  RTrigger_Corner_out.Q THEN
  g_bLaserOutCornerM := FALSE;
  bInCornerFalg := FALSE;
  g_dmaster_pressure := dPressure_note;
  g_nPower := nPower_note;
  g_dair_pressure := dAirPressure_note;
  g_doxygen_pressure := dOxygenPressure_note;
  g_dnitogen_pressure := dNirtogenPressure_note;
  g_nPwmFreq := nPwmFreq_note;
  g_nPwmDuty := nPwmDuty_note;
END_IF;

(*切割过程中随动跟随误差超过5,20ms报警*)
IF nLayerStartState = 500 AND ABS(g_fZFollowHeight - g_fZAxisHeight) > g_dFollowPosErrorAlarmValue AND Axis_Z.NCTOPLC.AXISSTATE = 9 AND g_ZFollowIn.DONE THEN
    TonFollowPosError(IN := TRUE,PT := T#20ms);
    IF TonFollowPosError.Q THEN
      TonFollowPosError(IN := FALSE);
      g_bFollowPosErrorAlarm := TRUE;
    END_IF;
ELSE
   TonFollowPosError(IN := FALSE);
  g_bFollowPosErrorAlarm := FALSE;
END_IF;






IF g_bPlcPauseBuffer AND nLayerStartState <> 0 THEN
  g_boCNCMoveDisable := TRUE;
  TON_NormalPiercingTime(IN := FALSE);
  TON_BurstingTime(IN := FALSE);
  Timer_Multil_High(IN := FALSE);
  Timer_Multil_Middle(IN := FALSE);
  Timer_Multil_Low(IN := FALSE);
  g_bZFollowExecute := FALSE;
  g_bZFollowClose := FALSE;
  g_bZRelExecute := FALSE;
  g_bZAbsExecute := FALSE;(*?*)
  g_fZAbsVelocity := 0.0;
  TON_PreCutDelay(IN :=FALSE);(*预切割延时定时器*)
 (* TON_PauseStopLaserDelay(IN :=FALSE);暂停关光延时*)
  TON_FirstGasDelay(IN :=FALSE);(*首点吹气延时定时器*)
  TON_ChangeGasDelay(IN :=FALSE);(*换气延时定时器*)
  TON_OpenGasDelay(IN :=FALSE);(*开气延时定时器*)
  TON_FrogLeapOpenGas(In := FALSE); (*蛙跳出气计时器*)
  TON_StopLightBlow(IN :=FALSE);(*停光吹气延时*)
  IF nLayerStartState < 600 THEN
    nLayerStartState := 600;
    TON_CloseGasDelay(IN :=FALSE);(*关气延时定时器*)
    bCloseGasDelayEnable := FALSE;
    g_ZMoveStop.EXECUTE := FALSE;
  END_IF;
  Ton_KernelWaitTime(IN := FALSE);
END_IF;

IF g_bPlcPauseBuffer AND nLayerEndState <> 0 THEN
  g_boCNCMoveDisable := TRUE;
  g_bLaserCuttingEnable := FALSE;
  g_bgas_enable := FALSE;
  g_bZFollowExecute := FALSE;
  g_bZFollowClose := FALSE;
  g_bZRelExecute := FALSE;
  g_fZRelVelocity := 0.0;
  g_bZAbsExecute := FALSE;
  g_fZAbsVelocity := 0.0;
  TON_CloseGasDelay(IN :=FALSE);(*关气延时定时器*)
  TON_FirstGasDelay(IN := FALSE);
  TON_FrogLeapOpenGas(In := FALSE); (*蛙跳出气计时器*)
  bCloseGasDelayEnable := FALSE;
  IF nLayerEndState < 700 THEN
    nLayerEndState := 700;
    g_ZMoveStop.EXECUTE := FALSE;
  END_IF;
END_IF;



IF g_bPlcResetBuffer THEN
  nLayerStartState := 0;
  nLayerEndState := 0;
  TON_NormalPiercingTime(IN := FALSE);
  TON_BurstingTime(IN := FALSE);
  Timer_Multil_High(IN := FALSE);
  Timer_Multil_Middle(IN := FALSE);
  Timer_Multil_Low(IN := FALSE);
  g_boLayerEndDone := TRUE;
  g_bLaserCuttingEnable := FALSE;
  g_bgas_enable := FALSE;
  g_bZFollowExecute := FALSE;
  g_bZFollowClose := FALSE;
  g_ZMoveStop.EXECUTE := FALSE;
  g_bZRelExecute := FALSE;
  g_fZRelVelocity := 0.0;
  g_bZAbsExecute := FALSE;(*?*)
  g_fZAbsVelocity := 0.0;
  g_boCNCMoveDisable := FALSE;
  g_bZLiftExecute := FALSE;
  bLookBackDone := FALSE;
  TON_PreCutDelay(IN :=FALSE);(*预切割延时定时器*)
  TON_PauseStopLaserDelay(IN :=FALSE);(*暂停关光延时*)
  TON_FirstGasDelay(IN :=FALSE);(*首点吹气延时定时器*)
  TON_ChangeGasDelay(IN :=FALSE);(*换气延时定时器*)
  g_bChangeGasFlag := FALSE;
  TON_OpenGasDelay(IN :=FALSE);(*开气延时定时器*)
  TON_CloseGasDelay(IN :=FALSE);(*关气延时定时器*)
  TON_FrogLeapOpenGas(In := FALSE); (*蛙跳出气计时器*)
  bCloseGasDelayEnable := FALSE;
  bUpLiftFlag := FALSE;
  bClaw3UpLiftFlag := FALSE;
  g_boClaw3UpLiftDone := FALSE;
  g_bProfileEnable := FALSE;
  g_bProfileLaserEnable := FALSE;
  g_bProfileFollowEnable := FALSE;(*板外切割关随动*)
  g_bFocusEnable := FALSE;
  g_bFProgressFocusAbs := FALSE;
  g_bFirstGas := FALSE;        (*复位首吹气标志位*)
  g_bProcessHalCloseFollowState:= FALSE;(*引脚关随动标志位*)
  g_bProcessHalCloseLaserState:=FALSE;(*引脚关关光标志位*)
  g_bProcessHalOpenLaserState:=FALSE;(*引脚开光标志位*)
  TonFlyCloseLightDelay(IN := FALSE);
  TonFlyOpenLightDelay(IN := FALSE);
  bZHeightJudgeOpen := FALSE;
  nZProtectstate := 0;
  g_bZHeightJudgeOpen := FALSE;
  Ton_KernelWaitTime(IN := FALSE);
  g_bForwardStatusFb := FALSE;
  g_bFallBackStatusFb := FALSE;
  g_bFollowPosErrorAlarm := FALSE;
  bFocusEnable := FALSE;
  Ton_FocusTimeout(IN := FALSE);
  bInCornerFalg := FALSE;
  bClaw2AoidingFlag := FALSE;
END_IF;

IF g_bPlcStartBuffer THEN
  bCurState := TRUE;
END_IF;
IF g_bPlcPauseBuffer THEN
  bCurState := FALSE;
END_IF;

g_diLastG00Time_rem := g_diG00Time_rem;



g_noTest1 := nLayerStartState;
g_noTest2 := nLayerEndState;
g_nLayerStart := nLayerStartState;
g_nLayerEnd := nLayerEndState;
g_doNestingIsUseSideCenter :=g_dNestingIsUseSideCenterM;
